WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY delivered_date DESC NULLS LAST, id) AS row_num FROM shipments) x WHERE row_num = 1) SELECT CASE WHEN cost >= 89 THEN 'LARGE' ELSE 'SMALL' END AS cost_tier, DATE_TRUNC('WEEK', delivered_date) AS week_start, SUM(cost) FILTER (WHERE carrier = 'Flash') AS flash_total_cost, STDDEV_SAMP(cost) AS cost_stddev, STDDEV_SAMP(cost) AS cost_stddev_2, COUNT(CASE WHEN carrier = 'FedEx' THEN 1 END) AS fedex_count FROM latest GROUP BY CASE WHEN cost >= 89 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('WEEK', delivered_date) ORDER BY flash_total_cost;
